import json,re
from pathlib import Path
from collections import Counter
from html.parser import HTMLParser
from xml.etree import ElementTree as ET
src=json.loads(Path('source.json').read_text())
ans=json.loads(Path('answer.json').read_text())
assert len(src)==len(ans)==24
assert len({x['source_id'] for x in ans})==24
class Text(HTMLParser):
 def __init__(self): super().__init__(); self.parts=[]
 def handle_data(self,data):self.parts.append(data)
def plain(x):
 h=Text();h.feed(x);return ' '.join(h.parts)
def nums(x):return Counter(re.findall(r'\\d+',x))
def refs(x):return Counter(re.findall(r'[LRD]\\.\\s*\\d+(?:-\\d+)*',x))
allowed={'p','br','table','thead','tbody','tfoot','tr','th','td','b','strong','i','em','u','sup','sub','ul','ol','li','div','span','blockquote'}
fields={'code_id','source_id','source_sha256','number','proposed_xml','reason','review_notes','status'}
for s,a in zip(src,ans):
 assert set(a)==fields
 for k in ('code_id','source_id','source_sha256','number'):assert a[k]==s[k]
 assert a['status']=='rewrite_draft' and all(isinstance(a[k],str) and a[k] for k in ('proposed_xml','reason','review_notes'))
 assert plain(a['proposed_xml'])"'!=plain(s['"'source_xml'])
 assert nums(a['proposed_xml'])==nums(s['source_xml']),s['number']
 assert refs(a['proposed_xml'])==refs(s['source_xml']),s['number']
 for el in ET.fromstring('<root>'+a['proposed_xml']+'</root>').iter():
  if el.tag=='root':continue
  assert el.tag in allowed
  assert all(k in {'rowspan','colspan'} and re.fullmatch('[0-9]+',v) for k,v in el.attrib.items())
 assert not re.search(r'https?://|texte inchangé|\\[.*\\]\\(',a['proposed_xml'],re.I)
 assert s['source_xml'].count('<table')==a['proposed_xml'].count('<table')
 for word in ('cent','dix','trois','six','tiers','moitié','deux'):
  count=lambda v:len(re.findall(r'\\b'+word+r'\\b',v,re.I))
  assert count(s['source_xml'])==count(a['proposed_xml']),(s['number'],word)
 if s['source_notes_xml']:
  for token in re.findall(r'\\d{4}-\\d+|\\b(?:2002|2003|2019|2020|2021|2023)\\b',s['source_notes_xml']):
   assert token in a['review_notes'],(s['number'],token)
print('24 articles vérifiés : identifiants exacts, champs complets, XML autorisé, chiffres et renvois identiques, quantités en lettres conservées, notes historiques reprises, aucun tableau omis.')
print('answer.json :',Path('answer.json').stat().st_size,'octets')
for a in ans:
 if a['number'] in ('L141-14','L142-2','L143-4'):
  s=next(s for s in src if s['number']==a['number'])
  print('\\nDernière correction',a['number'],'\\nSOURCE:',s['source_xml'],'\\nPROPOSITION:',a['proposed_xml'])
PY"

